/**
 * 点击「下一步」后是否自动生成下一步内容。
 *
 * 用户定调（2026-10-22）：「用户在某个阶段完成点击下一步的时候能不能直接生成下一步的
 * 内容，而不需要用户再点击生成？」——这里只判定**分析步**；确认步（第 1 步）仍是打开
 * 场景定义对话，组装步（交付物）由 `shouldAutoGenerateDelivery` 交给 DeliveryPanel
 * 写报告，不在本函数里替用户做选择。
 *
 * 已有内容、或服务端已在跑时不重复发起：前者让用户先看，后者等轮询对账收口。
 */
import type { ApiFlowStatus } from "../api";

export function shouldAutoGenerateStep(flow: ApiFlowStatus, targetStep: number): boolean {
  const target = flow.steps.find((s) => s.id === targetStep);
  if (!target || target.kind !== "分析") return false;
  return !target.ready && !target.running;
}

/**
 * 进入交付物步时是否自动写报告。
 *
 * 交付物不是分析步，不能走 `analysis.start()`；由 `DeliveryPanel` 在报告清单加载完后
 * 自行发起（已有报告、已在跑时不抢跑）。
 */
export function shouldAutoGenerateDelivery(flow: ApiFlowStatus, targetStep: number): boolean {
  const target = flow.steps.find((s) => s.id === targetStep);
  return target?.kind === "组装" && !target.ready && !target.running;
}
